<script>
/* XF 2.3 — Кнопка "Копировать всё" для [code] с сохранением переносов */
(function () {
  function escapeHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

  function getCodeText(block){
    // ищем текст внутри блока кода для разных разметок XF
    var el = block.querySelector('.bbCodeBlock-content pre, .bbCodeBlock-content code, pre.bbCodeCode, code.bbCodeCode, pre code') || block;
    var txt = (el.textContent || '').replace(/\u00A0/g, ' '); // no-break space -> space
    // конвертируем текстовые <br> в реальные переводы строк
    txt = txt
      .replace(/\r\n/g, '\n').replace(/\r/g, '\n')
      .replace(/&lt;br\s*\/?&gt;/gi, '\n')
      .replace(/<br\s*\/?>/gi, '\n');
    // убираем хвостовые пустые строки
    return txt.replace(/\n{3,}$/,'\n\n');
  }

  function buildHtmlFromText(txt){
    return '<div>'+ txt.split('\n').map(escapeHtml).join('<br>') +'</div>';
  }

  async function copyBoth(txt, html){
    if (navigator.clipboard && window.ClipboardItem) {
      const item = new ClipboardItem({
        'text/plain': new Blob([txt], {type:'text/plain'}),
        'text/html' : new Blob([html],{type:'text/html'})
      });
      await navigator.clipboard.write([item]);
    } else {
      // Фолбэк: копируем как текст
      const ta = document.createElement('textarea');
      ta.style.position='fixed'; ta.style.top='-1000px'; ta.value = txt;
      document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
    }
  }

  function addButtonTo(block){
    if (block.classList.contains('js-copyAllReady')) return;
    block.classList.add('js-copyAllReady');

    // куда вставлять кнопку — в заголовок блока кода, если есть
    var title = block.querySelector('.bbCodeBlock-title') || block;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'codeCopyAllButton';
    btn.textContent = 'Копировать всё';
    btn.addEventListener('click', async function(e){
      e.preventDefault();
      var txt  = getCodeText(block);
      var html = buildHtmlFromText(txt);
      try {
        await copyBoth(txt, html);
        btn.classList.add('is-copied'); setTimeout(()=>btn.classList.remove('is-copied'), 1500);
      } catch (_){ btn.classList.add('is-failed'); setTimeout(()=>btn.classList.remove('is-failed'), 1500); }
    });

    // размещаем справа
    title.style.position = 'relative';
    title.appendChild(btn);
  }

  function scan(){
    document.querySelectorAll('.bbCodeBlock--code, figure.bbCodeBlock.bbCodeBlock--code, .bbCodeBlock[data-xf-init~="code"]').forEach(addButtonTo);
  }

  // первичный проход
  document.addEventListener('DOMContentLoaded', scan);
  // и на подгрузки (лента, прокрутка и т.п.)
  new MutationObserver(function(){ scan(); }).observe(document.body, {childList:true, subtree:true});
})();
</script>


<script>
(function () {
  'use strict';

  const MOBILE_MQ = window.matchMedia('(max-width: 900px)'); // синхронизируй с @xf-responsiveMedium
  const CLAMP_PX = 160;                                      // тот же, что в extra.less

  function clampSignature(sigEl) {
    if (!sigEl || sigEl.dataset.sigClampInit === '1') return;
    sigEl.dataset.sigClampInit = '1';

    // Если подпись скрыта темой (display:none) — не работаем
    if (getComputedStyle(sigEl).display === 'none') return;

    // Оборачиваем содержимое в .sigClamp
    const wrap = document.createElement('div');
    wrap.className = 'sigClamp';
    while (sigEl.firstChild) wrap.appendChild(sigEl.firstChild);
    sigEl.appendChild(wrap);

    // Измеряем высоту уже отрисованного контента
    requestAnimationFrame(function () {
      if (wrap.scrollHeight <= CLAMP_PX + 8) {
        // Короткая подпись — раскладываем назад и выходим
        while (wrap.firstChild) sigEl.insertBefore(wrap.firstChild, wrap);
        wrap.remove();
        return;
      }

      // Кнопка «Показать всё / Свернуть»
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'sigClamp__toggle';
      btn.setAttribute('aria-expanded', 'false');
      btn.innerHTML = '<span class="state-more">Показать всё</span><span class="state-less">Свернуть</span>';

      btn.addEventListener('click', function () {
        const expanded = wrap.classList.toggle('sigClamp--expanded');
        btn.setAttribute('aria-expanded', expanded ? 'true' : 'false');
      });

      sigEl.appendChild(btn);
    });
  }

  function initClamp(root) {
    if (!MOBILE_MQ.matches) return; // только на мобилках
    (root || document).querySelectorAll('.message-signature').forEach(clampSignature);
  }

  // Первичная инициализация
  document.addEventListener('DOMContentLoaded', function () { initClamp(document); });

  // Повторная инициализация при AJAX-навигации XenForo
  document.addEventListener('xf:reinit', function (e) { initClamp(e.target || document); });

  // Если пользователь меняет ширину экрана — на мобиле включаем, на десктопе не трогаем
  MOBILE_MQ.addEventListener?.('change', function (e) {
    if (e.matches) initClamp(document);
  });
})();
</script>	

